export function sanitizeProgress(value){
 const known=new Set(lessons.map(l=>l.id));
 const completed=Array.isArray(value?.completed)?[...new Set(value.completed.filter(id=>known.has(id)))]:[];
 const dates=Array.isArray(value?.dates)?[...new Set(value.dates.filter(d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)))].slice(-366):[];
 return {version:1,completed,dates};
}
const regular=u=>lessons.filter(l=>l.unit===u&&l.type!=='checkpoint');
export const checkpointOf=u=>lessons.find(l=>l.unit===u&&l.type==='checkpoint');
export const unitPassed=(u,p)=>{const c=checkpointOf(u);return !!c&&p.completed.includes(c.id);};
export function unitOpen(u,p){if(u===1)return true;const prev=regular(u-1);return prev.length>0&&(unitPassed(u-1,p)||prev.every(l=>p.completed.includes(l.id)));}
export function nextLesson(p){return lessons.find(l=>!p.completed.includes(l.id)&&canOpen(l.id,p)&&!(l.type!=='checkpoint'&&unitPassed(l.unit,p)));}
export function canOpen(id,p){const l=lessons.find(x=>x.id===id);if(!l||!unitOpen(l.unit,p))return false;if(l.type==='checkpoint'||unitPassed(l.unit,p))return true;const ls=regular(l.unit);return ls.slice(0,ls.indexOf(l)).every(x=>p.completed.includes(x.id));}
export function totalXP(p){return lessons.filter(l=>p.completed.includes(l.id)).reduce((n,l)=>n+l.xp,0);}
export function complete(p,id,date){if(!lessons.some(l=>l.id===id)||!canOpen(id,p))return p;return sanitizeProgress({completed:[...p.completed,id],dates:[...p.dates,date]});}
export function grade(questions,answers){return questions.map((q,i)=>{const a=answers[i];if(q.choices)return a===q.answer;const n=Number(String(a??'').trim().replace(',','.'));return String(a??'').trim()!==''&&Number.isFinite(n)&&Math.abs(n-q.answer)<=(q.tolerance||0);});}
